params.body:
{
  "query": "SELECT t.id_tramitacao, t.id_processo, cp.numero_processo, t.evento, te.descricao AS evento_descricao, t.id_tramitacao_situacao, ts.descricao AS tramitacao_situacao_descricao, cp.grupo_trabalho AS codigo_grupo_trabalho, tgt.descricao AS grupo_trabalho_descricao, t.data_hora_lan, t.ag_data_hora, t.texto, t.id_pessoa_solicitante, t.id_pessoa_solicitada, t.id_pessoa_atribuida, t.tipo, t.id_tramitacao_motivo, t.prazo_data_inicio, t.prazo_tipo_contagem, t.cumprido_em, t.cumprido_por, t.justificativa, t.update_data_hora, t.update_usuario FROM cad_processo cp STRAIGHT_JOIN tramitacao t ON t.id_processo = cp.pj AND t.id_tramitacao_situacao = 0 AND t.evento IN ('PDE', 'FTP', 'TRC', 'FBA', 'FCF') AND t.data_hora_lan >= NOW() - INTERVAL 30 DAY LEFT JOIN tab_grupo_trabalho tgt ON tgt.codigo = cp.grupo_trabalho LEFT JOIN tab_evento te ON te.sigla = t.evento LEFT JOIN tramitacao_situacao ts ON ts.id_tramitacao_situacao = t.id_tramitacao_situacao WHERE cp.grupo_trabalho = 2 LIMIT 1000"
}
